


/** What a store lets buyers do to their own subscriptions. Send at least one field; each field you omit takes its default. */ export type BuyerCapabilitiesInput = { /** Reasons a buyer is asked to choose from when canceling, in the order shown. Empty: the buyer is not asked. When the list is not empty, a buyer's cancellation_reason_code must be one of them. maxItems: 8. */ "cancellation_reasons"?: Array<"too_expensive" | "missing_features" | "switched_service" | "unused" | "customer_service" | "too_complex" | "low_quality" | "other">; /** When a subscription a buyer cancels ends. end_of_period: when the current billing period ends. buyer_chooses: the buyer picks the end of the period or right away. A trialing, paused, or incomplete subscription, or one whose first paid period never started, ends right away either way. */ "cancellation_timing"?: "end_of_period" | "buyer_chooses"; /** Whether buyers may pause, and for how long. Omit it to let buyers pause with no limit. */ "pause"?: { /** Whether buyers may pause. When false, a buyer's pause returns PAUSE_NOT_ALLOWED. */ "enabled"?: boolean; /** The longest pause a buyer may choose, in billing periods. When set, a buyer's pause must send pause_duration_cycles from 1 to this value. Omit it for no limit, which also lets a buyer pause until they resume. Format: int32. minimum: 1. maximum: 12. */ "max_cycles"?: number; }; /** The offer a buyer sees before canceling. The buyer can always decline it and cancel. Omit it for no offer. */ "retention_offer"?: { /** none: no offer. pause_instead: offer to pause for pause_cycles billing periods instead of canceling. pause_instead needs pausing turned on. */ "kind"?: "none" | "pause_instead"; /** Billing periods the offered pause lasts. Required when kind is pause_instead, and at most pause.max_cycles when that is set. Not allowed with kind none. Format: int32. minimum: 1. maximum: 12. */ "pause_cycles"?: number; }; };
